#!/bin/bash
set -euxo pipefail
yum install -y amazon-cloudwatch-agent
cat > /usr/local/bin/fa-cloudwatch-app.sh <<'EOF'
#!/bin/bash
while true; do
  echo "$(date -Is) level=INFO service=fa-cloudwatch-app message=heartbeat"
  sleep 30
  echo "$(date -Is) level=ERROR service=fa-cloudwatch-app message=synthetic-error-for-training"
  sleep 30
done
EOF
chmod 755 /usr/local/bin/fa-cloudwatch-app.sh
cat > /etc/systemd/system/fa-cloudwatch-app.service <<'EOF'
[Unit]
Description=fa-cloudwatch harmless training log generator
After=network.target

[Service]
ExecStart=/bin/bash -c '/usr/local/bin/fa-cloudwatch-app.sh >> /var/log/fa-cloudwatch-app.log 2>&1'
Restart=always

[Install]
WantedBy=multi-user.target
EOF
systemctl daemon-reload
systemctl enable --now fa-cloudwatch-app.service
cat > /opt/aws/amazon-cloudwatch-agent/etc/amazon-cloudwatch-agent.json <<'EOF'
{
  "agent": {
    "metrics_collection_interval": 60,
    "region": "eu-west-2",
    "run_as_user": "root"
  },
  "metrics": {
    "namespace": "fa-cloudwatch/Agent",
    "append_dimensions": {
      "InstanceId": "${aws:InstanceId}"
    },
    "metrics_collected": {
      "cpu": {
        "measurement": ["cpu_usage_idle", "cpu_usage_user", "cpu_usage_system"],
        "metrics_collection_interval": 60
      },
      "mem": {
        "measurement": ["mem_used_percent"],
        "metrics_collection_interval": 60
      },
      "disk": {
        "measurement": ["disk_used_percent"],
        "resources": ["/"],
        "metrics_collection_interval": 60
      }
    }
  },
  "logs": {
    "logs_collected": {
      "files": {
        "collect_list": [
          {
            "file_path": "/var/log/fa-cloudwatch-app.log",
            "log_group_name": "/fa-cloudwatch/application",
            "log_stream_name": "{instance_id}",
            "retention_in_days": 7
          }
        ]
      }
    }
  }
}
EOF
/opt/aws/amazon-cloudwatch-agent/bin/amazon-cloudwatch-agent-ctl -a fetch-config -m ec2 -c file:/opt/aws/amazon-cloudwatch-agent/etc/amazon-cloudwatch-agent.json -s
